#!/usr/bin/env python3
"""
Decode ROCgdb VGPR output (32-bit per lane) as packed fp16 [low16, high16].
Paste the list from (gdb) p $v22 etc. into v22_v25 below, or pass from stdin.

Usage:
  python3 decode_vgpr_fp16.py
  # or: echo "1006632960 1344294912 ..." | python3 decode_vgpr_fp16.py
"""
import struct
import sys

def u16_to_fp16(x):
    """Interpret uint16 as IEEE 754 binary16."""
    return struct.unpack('e', struct.pack('H', x & 0xFFFF))[0]

def decode_vgpr_32(values):
    """Decode a list of 32-bit values as [low_fp16, high_fp16] per lane."""
    for lane, v in enumerate(values):
        low16 = v & 0xFFFF
        high16 = (v >> 16) & 0xFFFF
        lo_f = u16_to_fp16(low16)
        hi_f = u16_to_fp16(high16)
        yield lane, v, low16, high16, lo_f, hi_f

